mapper.select:
SELECT * FROM ( SELECT /* utb_customer: 기본 및 분류 코드 */ c.customer_seq AS "customerSeq", c.office_seq AS "officeSeq", c.biz_info_seq AS "bizInfoSeq", c.client_category_code AS "clientCategoryCode", c.client_category_code AS "clientDiv", c.applicant_category_code AS "applicantCategoryCode", c.applicant_category_code AS "appManDiv", c.corp_category_code AS "corpCategoryCode", c.corp_category_code AS "corpDiv", c.attorney_category_code AS "attorneyCategoryCode", c.attorney_category_code AS "attorneyDiv",
/* utb_customer: 명칭 및 상세 */ c.client_name_ko AS "clientNameKo", c.client_name_en AS "clientNameEn", c.client_name_ch AS "clientNameCh", c.client_name_jp AS "clientNameJp", c.company_name AS "companyName", c.dept_name AS "deptName", c.customer_position AS "customerPosition", /* VO 필드명 유지 */ c.client_name_ko AS "customerName", /* 검색용 */
/* utb_customer: [출원인] 주소 및 연락처 */ c.app_zip_code AS "appZipCode", c.app_address AS "appAddress", c.app_tel AS "appTel", c.app_fax AS "appFax",
/* utb_customer: [담당자] 주소 및 연락처 (기존 누락분 추가) */ c.contact_zip_code AS "contactZipCode", c.contact_address AS "contactAddress", c.contact_person AS "contactPerson", c.contact_tel AS "contactTel", c.contact_fax AS "contactFax",
/* utb_customer: [기타] 주소 및 연락처 (기존 누락분 추가) */ c.etc_zip_code AS "etcZipCode", c.etc_address AS "etcAddress", c.etc_tel AS "etcTel", c.etc_fax AS "etcFax",
/* utb_customer: [해외] 주소 및 연락처 (기존 누락분 추가) */ c.oversea_zip_code AS "overseaZipCode", c.oversea_address AS "overseaAddress", c.oversea_tel AS "overseaTel", c.oversea_fax AS "overseaFax",
/* utb_customer: 기타 등록 및 관리 정보 */ c.country_code AS "countryCode", c.resident_reg_no AS "residentRegNo", c.corp_reg_no AS "corpRegNo", c.kipo_client_no AS "kipoClientNo", c.kipo_client_no AS "patentCustNo1", c.kipo_client_no AS "patentCustNo2", /* 검색용 */ c.manager_name AS "managerName", c.manager_name AS "bizContactName", c.manager_name AS "adminMgrNm", /* 검색용 */ c.general_mandate_no AS "generalMandateNo", c.email AS "email", c.email AS "bizEmail", c.note AS "note", c.note AS "memo", c.app_tel AS "telNo", b.ceo_name AS "bizCeo", c.mobile AS "mobile", c.homepage AS "homepage", c.registration_date AS "registrationDate", c.create_at AS "createAt", /* 검색용 */
/* utb_biz_info: 사업자 정보 조인 */ b.biz_reg_no AS "bizRegNo", b.biz_workplace_no AS "bizWorkplaceNo", b.biz_corp_name AS "bizCorpName", b.biz_corp_name AS "bizName", /* 검색용 */ b.ceo_name AS "ceoName", b.biz_addr AS "bizAddr", b.biz_type AS "bizType", b.biz_kind AS "bizKind", b.reg_discount_code AS "regDiscountCode", b.reduction_reason AS "reductionReason", TO_CHAR(b.reduction_issue_date, 'YYYYMMDD') AS "docIssueDate", TO_CHAR(b.discount_closing_date, 'YYYYMMDD') AS "exemptionPeriod" FROM utb_customer c LEFT JOIN utb_biz_info b ON c.biz_info_seq = b.biz_info_seq WHERE c.office_seq = #{request.officeSeq} AND c.del_yn = 'N' ) Z WHERE 1=1
ORDER BY Z."createAt" DESC LIMIT #{request.pageSize} OFFSET #{request.offSet}

SELECT *
FROM utb_wrappermandate
WHERE customer_seq = #{tblSeq}
  AND office_seq = #{officeSeq}
  AND del_yn = 'N'
ORDER BY sort_order ASC, mandate_date DESC
    LIMIT #{pageSize} OFFSET #{offSet}

SELECT *
FROM utb_wrappermandate
WHERE wrappermandate_seq = #{wrappermandateSeq}
  AND office_seq = #{officeSeq}

SELECT * FROM ( SELECT DISTINCT ON (u.user_info_seq,p.office_seq ) p.tbl_seq AS "tbl_seq", p.office_seq AS "office_seq", p.participant_code AS "participant_code", p.participant_seq AS "participant_seq", u.user_info_seq AS "user_info_seq", u.user_name_ko AS "user_name_ko", u.user_name_ko AS "customerName", /* 검색용 */ u.user_mobile_no AS "user_mobile_no", u.dept_name AS "dept_name", u.user_tel_no AS "user_tel_no", u.user_position AS "user_position", u.user_fax_no AS "user_fax_no", u.user_email AS "user_email", u.user_email AS "email", /* 검색용 */ u.user_post_no AS "user_post_no", u.user_addr AS "user_addr", u.user_addr_detail AS "user_addr_detail", p.note AS "note", u.etax_yn AS "etax_yn", p.create_at AS "createAt" /* 검색 정렬용 */ FROM utb_participant p INNER JOIN utb_user_info u ON p.user_info_seq = u.user_info_seq WHERE 1=1
/* tblSeq가 파라미터로 넘어온 경우에만 조건 추가 */
AND p.tbl_seq = #{request.tblSeq}
AND p.participant_code = #{participantCode}
AND p.office_seq = #{request.officeSeq} AND p.del_yn = 'N' AND u.del_yn = 'N' ORDER BY u.user_info_seq, p.office_seq, p.create_at DESC ) Z WHERE 1=1
ORDER BY Z."createAt" DESC LIMIT #{request.pageSize} OFFSET #{request.offSet}

SELECT m.customer_mapp_seq, m.tbl_seq, m.customer_seq, COALESCE(c.client_name_ko, '') AS related_customer_name, COALESCE(c.client_name_en, '') AS client_name_en, COALESCE(c.app_address, '') AS app_address, COALESCE(c.contact_address, '') AS contact_address, COALESCE(c.kipo_client_no, '') AS kipo_client_no, m.relation_code FROM utb_customer_mapp m LEFT JOIN utb_customer c ON m.customer_seq = c.customer_seq WHERE m.tbl_seq = #{req.tblSeq} AND m.office_seq = #{req.officeSeq}
AND m.customer_category_code IS NULL
AND m.customer_category_code = #{customerCategoryCode}
AND m.del_yn = 'N' ORDER BY m.create_at DESC LIMIT #{req.pageSize} OFFSET #{req.offSet}

SELECT
    count(*)
FROM utb_customer_mapp
WHERE customer_mapp_seq = #{tblSeq}
  AND customer_category_code = #{customerCategoryCode}
  AND del_yn = 'N'

